// Vocabulary part h4 (plan.md VOCABULARY): glazing, ledgestone, carport, car, mailbox, garden lamp, and the
// furniture for the living room, the pit and the bedrooms. Every helper takes its position (and facing) as arguments.
// Each writes only into air and returns { placed, skipped } (skipped = a cell that was not air, or outside the grid);
// none touches y <= 0, where the ground, sand and floors belong to earlier parts.
import { DIRS, OPPOSITE, face, B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

const BEAM_X0 = 10, BEAM_STEP = 3; // beam lines x = 10, 13, ..., 31 (plan.md, structural rhythm)
const BED_COLOURS = ["orange", "cyan", "yellow", "light_blue", "white"];

// one call's writer: places a block only into air inside the grid, and counts what it could not place
function writer(g) {
  const out = { placed: 0, skipped: 0 };
  const put = (x, y, z, block, state, nbt) => {
    if (g.inBounds(x, y, z) && g.isAir(x, y, z)) { g.set(x, y, z, block, state, nbt); out.placed++; } else out.skipped++;
  };
  return { put, out };
}

// inclusive run from a to b, in either order
const span = (a, b) => Array.from({ length: Math.abs(b - a) + 1 }, (_, i) => Math.min(a, b) + i);

// seeded PRNG (mulberry32) so the same seed always gives the same wall
function mulberry32(seed) {
  let a = seed | 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Glass panes in a run along x: x0..x1 at row z, y0..y1 (the south garden wall, the atrium ring). */
----
// Vocabulary helpers from plan.md's VOCABULARY, as build-library calls. Each takes the grid first, then world
// coordinates (plan.md's own), then its facing where it has one, then `opts` last.
// Rules every helper keeps: it writes only its own footprint; only into air (never over an earlier part's block) unless
// opts.overwrite; and never below its lowest cell (the ground, sand and floor under it belong to earlier parts).
// stepping_pad also replaces ground cover (dirt, grass, sand, gravel) on its own y=0 row: that is the surface it sits on.
// Each helper returns { placed, skipped }, where skipped lists [x, y, z, block] the rule refused.
import { B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

const AIR = new Set(["minecraft:air", "minecraft:cave_air", "minecraft:void_air"]);
const COVER = new Set(["minecraft:dirt", "minecraft:grass_block", "minecraft:sand", "minecraft:gravel"]);

// One call's writer: at(x, y, z, [block, state, nbt]) places the block only where the rule allows it.
function painter(g, { overwrite = false, ground = false } = {}) {
  const out = { placed: 0, skipped: [] };
  const at = (x, y, z, spec) => {
    const here = g.blockAt(x, y, z);
    if (overwrite || AIR.has(here) || (ground && COVER.has(here))) {
      g.set(x, y, z, ...spec);
      out.placed++;
    } else out.skipped.push([x, y, z, here]);
  };
  return { at, out };
}

/** Dark oak post, axis y, at (x, z) from y0 to y1 (the post and header rhythm: y=2..4). */
----
